```python
from watcher_runtime import harness
from watcher_runtime.adapters import weather_openmeteo

LATITUDE = 52.3909
LONGITUDE = 13.0645
TARGET_DATE = "2026-10-03"

try:
    data = weather_openmeteo.fetch(LATITUDE, LONGITUDE)
except Exception as exc:
    harness.fail("I couldn't retrieve the weather forecast just now.")
else:
    forecast = data.get("daily", [])
    rain_expected = False
    for day in forecast:
        if day.get("date") == TARGET_DATE:
            precip = day.get("precipitation_mm", 0.0)
            code = day.get("weather_code")
            if precip > 0.0:
                rain_expected = True
                break
            # WMO rain codes: 51-67, 80-82
            if isinstance(code, int) and (51 <= code <= 67 or 80 <= code <= 82):
                rain_expected = True
                break
            break  # found the day, no rain indicated
    if rain_expected:
        harness.emit(
            "act_now",
            "Rain is forecast for Potsdam on your wedding day.",
            "weather_openmeteo",
            {"date": TARGET_DATE},
            next_check_s=21600
        )
    else:
        harness.emit(
            "ok",
            "No rain expected in Potsdam on your wedding day.",
            "weather_openmeteo",
            {"date": TARGET_DATE},
            next_check_s=21600
        )
